import React from 'react';
import Error403Svg from './Error403SVG';
import { Container, Description, ErrorImage } from '../Error.styles';
import { Heading, Paragraph } from '../../typography';
import { Button } from '../../button';

export interface Error403Props {
  header?: string;
  description?: string;
  buttonText?: string;
  hasButton?: boolean;
  onButtonClick?: () => void;
}

const Error403 = ({
  header = 'Hmm... Access denied!',
  description = "It looks like you don't have permission to access this page.",
  buttonText = 'Home',
  hasButton = true,
  onButtonClick,
}: Error403Props): JSX.Element => (
  <Container data-testid="error403-component">
    <ErrorImage error="403">
      <Error403Svg />
    </ErrorImage>
    <Heading size="H2">{header}</Heading>
    <Description>
      <Paragraph size="basis">{description}</Paragraph>
    </Description>
    {hasButton && (
      <Button onClick={onButtonClick} size="large">
        {buttonText}
      </Button>
    )}
  </Container>
);

export default Error403;
